mapper.select:
AND (c.simplified like concat('%', #{searchValue}, '%') or c.original like concat('%', #{searchValue}, '%') or c.translation like concat('%', #{searchValue}, '%') or c.tags like concat('%', #{searchValue}, '%'))
AND c.volume_id = #{volumeId}
AND c.reign_id = #{reignId}
order by c.volume_id, c.reign_id, c.number
